def end_legacy_staff_sessions(apps, schema_editor):
    """End every session staff held before P1-B.

    Tokens issued before P1-B carry no `av` claim and count as version 0, and
    refresh rotation would keep them alive forever, so staff would never meet
    the new emailed-code step. Bumping auth_version once ends them. Customers
    are left signed in.
    """
    User = apps.get_model('users', 'User')
    # update() cannot follow the join's distinct(), so select the ids first.
    staff_ids = (
        User.objects.filter(Q(is_staff=True) | Q(is_superuser=True) | Q(roles__isnull=False))
        .values('pk')
    )
    User.objects.filter(pk__in=staff_ids).update(auth_version=F('auth_version') + 1)


